package eval

func inventoryStacksSuite() Suite {
	base := concentrationSuite()
	return Suite{ID: "054-inventory-stacks", Name: "Campaign Play 054: Inventory Stacks", Tests: append(base.Tests,
		playTest("play-inventory-empty", "Campaign member reads an empty character inventory", "GET", "/v1/play/campaigns/play-2/characters/play-char-b/inventory/items", nil, map[string]string{"Authorization": playerAAuth}, 200, map[string]any{"character_id": "play-char-b", "items": []any{}}),
		playTest("play-inventory-add-non-owner", "Non-owner cannot add to a character inventory", "POST", "/v1/play/campaigns/play-2/characters/play-char-w/inventory/items", map[string]any{"item_id": "torch", "quantity": 1}, map[string]string{"Authorization": playerBAuth}, 403, nil),
		playTest("play-inventory-add-unknown-item", "Adding an unknown item is rejected", "POST", "/v1/play/campaigns/play-2/characters/play-char-w/inventory/items", map[string]any{"item_id": "longsword", "quantity": 1}, map[string]string{"Authorization": playerAAuth}, 400, nil),
		playTest("play-inventory-add-invalid-quantity", "Adding a non-positive quantity is rejected", "POST", "/v1/play/campaigns/play-2/characters/play-char-w/inventory/items", map[string]any{"item_id": "healing-potion", "quantity": 0}, map[string]string{"Authorization": playerAAuth}, 400, nil),
		playTest("play-inventory-add-potion", "Owner adds a stackable item", "POST", "/v1/play/campaigns/play-2/characters/play-char-w/inventory/items", map[string]any{"item_id": "healing-potion", "quantity": 2}, map[string]string{"Authorization": playerAAuth}, 201, map[string]any{"character_id": "play-char-w", "item_id": "healing-potion", "quantity": 2, "total_quantity": 2}),
		playTest("play-inventory-stack-potion", "Repeated adds increment the held stack", "POST", "/v1/play/campaigns/play-2/characters/play-char-w/inventory/items", map[string]any{"item_id": "healing-potion", "quantity": 3}, map[string]string{"Authorization": playerAAuth}, 201, map[string]any{"character_id": "play-char-w", "item_id": "healing-potion", "quantity": 3, "total_quantity": 5}),
		playTest("play-inventory-add-torch", "Owner adds a second item type", "POST", "/v1/play/campaigns/play-2/characters/play-char-w/inventory/items", map[string]any{"item_id": "torch", "quantity": 1}, map[string]string{"Authorization": playerAAuth}, 201, map[string]any{"character_id": "play-char-w", "item_id": "torch", "quantity": 1, "total_quantity": 1}),
		playTest("play-inventory-read-stable", "Campaign member reads items in lexicographic order", "GET", "/v1/play/campaigns/play-2/characters/play-char-w/inventory/items", nil, map[string]string{"Authorization": playerBAuth}, 200, map[string]any{"character_id": "play-char-w", "items": []any{map[string]any{"item_id": "healing-potion", "quantity": 5}, map[string]any{"item_id": "torch", "quantity": 1}}}),
		playTest("play-inventory-delete-non-owner", "Non-owner cannot remove from a character inventory", "DELETE", "/v1/play/campaigns/play-2/characters/play-char-w/inventory/items/torch", map[string]any{"quantity": 1}, map[string]string{"Authorization": playerBAuth}, 403, nil),
		playTest("play-inventory-delete-invalid-quantity", "Removing a non-positive quantity is rejected", "DELETE", "/v1/play/campaigns/play-2/characters/play-char-w/inventory/items/healing-potion", map[string]any{"quantity": 0}, map[string]string{"Authorization": playerAAuth}, 400, nil),
		playTest("play-inventory-delete-unknown-item", "Removing an unknown item is rejected", "DELETE", "/v1/play/campaigns/play-2/characters/play-char-w/inventory/items/longsword", map[string]any{"quantity": 1}, map[string]string{"Authorization": playerAAuth}, 400, nil),
		playTest("play-inventory-delete-potion", "Owner removes part of a held stack", "DELETE", "/v1/play/campaigns/play-2/characters/play-char-w/inventory/items/healing-potion", map[string]any{"quantity": 2}, map[string]string{"Authorization": playerAAuth}, 200, map[string]any{"character_id": "play-char-w", "item_id": "healing-potion", "quantity": 2, "total_quantity": 3}),
		playTest("play-inventory-delete-underflow", "Removing more than held is rejected", "DELETE", "/v1/play/campaigns/play-2/characters/play-char-w/inventory/items/healing-potion", map[string]any{"quantity": 99}, map[string]string{"Authorization": playerAAuth}, 409, nil),
	)}
}
